import{_ as n,o as a,c as e,a5 as p}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"46. 使用 errno 和 perror 进行错误检查","description":"The Little Book of C 中文版 — 46. 使用 errno 和 perror 进行错误检查","frontmatter":{"title":"46. 使用 errno 和 perror 进行错误检查","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","05-输入输出与文件","中文"],"description":"The Little Book of C 中文版 — 46. 使用 errno 和 perror 进行错误检查","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":46,"sidebarWeight":46,"alternateZh":"/posts/c教程/zh-CN/05-输入输出与文件/046-Error Checking with errno and perror","alternateEn":"/posts/c教程/en-US/05-Input Output and Files/046-Error Checking with errno and perror"},"headers":[],"relativePath":"posts/c教程/zh-CN/05-输入输出与文件/046-Error Checking with errno and perror.md","filePath":"posts/c教程/zh-CN/05-输入输出与文件/046-Error Checking with errno and perror.md","lastUpdated":1790163617000}'),t={name:"posts/c教程/zh-CN/05-输入输出与文件/046-Error Checking with errno and perror.md"};function o(r,s,i,l,c,d){return a(),e("div",null,[...s[0]||(s[0]=[p(`<p>[English version](/posts/c教程/en-US/05-Input Output and Files/046-Error Checking with errno and perror)</p><p>即使写得最好的 C 程序也可能会遇到错误、文件丢失、权限问题、被零除或内存分配失败。与某些引发异常的语言不同，C 使用返回值和名为的全局变量手动报告错误<code>errno</code>.</p><p>了解如何使用<code>errno</code>,<code>perror()</code>， 和<code>strerror()</code>对于编写能够优雅且信息丰富地失败的健壮的生产级 C 程序至关重要。</p><h4 id="errno-背后的想法" tabindex="-1">errno 背后的想法 <a class="header-anchor" href="#errno-背后的想法" aria-label="Permalink to &quot;errno 背后的想法&quot;">​</a></h4><p><code>errno</code>是一个全局整数（在<code>&lt;errno.h&gt;</code>）每当库函数失败时存储错误代码。</p><ul><li>成功后，大多数功能都会离开<code>errno</code>不变。</li><li>一旦失败，他们通常会设置<code>errno</code>并返回一个错误值（通常<code>NULL</code>,<code>-1</code>， 或者<code>0</code>取决于功能）。</li><li>必须先检查返回值，然后才应该检查<code>errno</code>.</li></ul><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;errno.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    FILE *fp = fopen(&quot;missing.txt&quot;, &quot;r&quot;);</span></span>
<span class="line"><span>    if (!fp) {</span></span>
<span class="line"><span>        printf(&quot;Error code: %d\\n&quot;, errno);</span></span>
<span class="line"><span>        perror(&quot;fopen failed&quot;);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error code: 2</span></span>
<span class="line"><span>fopen failed: No such file or directory</span></span></code></pre></div><h4 id="常见错误代码" tabindex="-1">常见错误代码 <a class="header-anchor" href="#常见错误代码" aria-label="Permalink to &quot;常见错误代码&quot;">​</a></h4><table tabindex="0"><thead><tr><th>代码</th><th>名称</th><th>意义</th></tr></thead><tbody><tr><td>2</td><td><code>ENOENT</code></td><td>没有这样的文件或目录</td></tr><tr><td>13</td><td><code>EACCES</code></td><td>权限被拒绝</td></tr><tr><td>12</td><td><code>ENOMEM</code></td><td>内存不够</td></tr><tr><td>22</td><td><code>EINVAL</code></td><td>无效参数</td></tr><tr><td>17</td><td><code>EEXIST</code></td><td>文件已存在</td></tr><tr><td>5</td><td><code>EIO</code></td><td>输入/输出错误</td></tr><tr><td>111</td><td><code>ECONNREFUSED</code></td><td>连接被拒绝（网络）</td></tr></tbody></table><p>包括<code>&lt;errno.h&gt;</code>使用这些符号名称：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if (errno == ENOENT) printf(&quot;File missing.\\n&quot;);</span></span></code></pre></div><h4 id="使用-perror" tabindex="-1">使用 perror() <a class="header-anchor" href="#使用-perror" aria-label="Permalink to &quot;使用 perror()&quot;">​</a></h4><p><code>perror()</code>打印一条人类可读的错误消息<code>stderr</code>，基于当前值<code>errno</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>perror(&quot;File open error&quot;);</span></span></code></pre></div><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;errno.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    FILE *f = fopen(&quot;ghost.txt&quot;, &quot;r&quot;);</span></span>
<span class="line"><span>    if (!f)</span></span>
<span class="line"><span>        perror(&quot;Unable to open file&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Unable to open file: No such file or directory</span></span></code></pre></div><h4 id="使用-strerror" tabindex="-1">使用 strerror() <a class="header-anchor" href="#使用-strerror" aria-label="Permalink to &quot;使用 strerror()&quot;">​</a></h4><p>如果您想在自己的格式化输出中使用错误消息，请使用<code>strerror()</code>从<code>&lt;string.h&gt;</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;string.h&gt;</span></span>
<span class="line"><span>#include &lt;errno.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    FILE *f = fopen(&quot;/root/secret.txt&quot;, &quot;r&quot;);</span></span>
<span class="line"><span>    if (!f)</span></span>
<span class="line"><span>        printf(&quot;Error (%d): %s\\n&quot;, errno, strerror(errno));</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error (13): Permission denied</span></span></code></pre></div><h4 id="小代码-强大的文件阅读器" tabindex="-1">小代码：强大的文件阅读器 <a class="header-anchor" href="#小代码-强大的文件阅读器" aria-label="Permalink to &quot;小代码：强大的文件阅读器&quot;">​</a></h4><p>这是一个简单的文件读取器，可以在每一步检查错误：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;string.h&gt;</span></span>
<span class="line"><span>#include &lt;errno.h&gt;</span></span>
<span class="line"><span>int main(int argc, char *argv[]) {</span></span>
<span class="line"><span>    if (argc != 2) {</span></span>
<span class="line"><span>        fprintf(stderr, &quot;Usage: %s &lt;filename&gt;\\n&quot;, argv[0]);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    FILE *fp = fopen(argv[1], &quot;r&quot;);</span></span>
<span class="line"><span>    if (!fp) {</span></span>
<span class="line"><span>        fprintf(stderr, &quot;Error opening %s: %s\\n&quot;, argv[1], strerror(errno));</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    char buf[128];</span></span>
<span class="line"><span>    while (fgets(buf, sizeof(buf), fp))</span></span>
<span class="line"><span>        printf(&quot;%s&quot;, buf);</span></span>
<span class="line"><span>    if (ferror(fp)) {</span></span>
<span class="line"><span>        fprintf(stderr, &quot;Error reading file: %s\\n&quot;, strerror(errno));</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    fclose(fp);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>用法：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./readfile poem.txt</span></span></code></pre></div><p>如果文件丢失：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error opening poem.txt: No such file or directory</span></span></code></pre></div><h4 id="清除并重置errno" tabindex="-1">清除并重置errno <a class="header-anchor" href="#清除并重置errno" aria-label="Permalink to &quot;清除并重置errno&quot;">​</a></h4><p>某些功能可以设置<code>errno</code>即使他们后来成功了。为了安全起见，您可以在调用之前清除它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;errno.h&gt;</span></span>
<span class="line"><span>errno = 0;</span></span>
<span class="line"><span>FILE *f = fopen(&quot;file.txt&quot;, &quot;r&quot;);</span></span>
<span class="line"><span>if (!f) perror(&quot;fopen&quot;);</span></span></code></pre></div><p>这可确保您不会读取先前操作中遗留的错误。</p><h4 id="检查其他系统错误" tabindex="-1">检查其他系统错误 <a class="header-anchor" href="#检查其他系统错误" aria-label="Permalink to &quot;检查其他系统错误&quot;">​</a></h4><p><code>errno</code>不限于文件 I/O，它适用于许多系统调用和库函数：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>#include &lt;errno.h&gt;</span></span>
<span class="line"><span>#include &lt;string.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    FILE *f = fopen(&quot;/dev/full&quot;, &quot;w&quot;); // special Linux device that fails on write</span></span>
<span class="line"><span>    if (f) {</span></span>
<span class="line"><span>        if (fputc(&#39;A&#39;, f) == EOF)</span></span>
<span class="line"><span>            perror(&quot;Write failed&quot;);</span></span>
<span class="line"><span>        fclose(f);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Write failed: No space left on device</span></span></code></pre></div><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p><code>errno</code>及其助手（<code>perror</code>,<code>strerror</code>）让你的程序在出现问题时能够自我解释。这对于以下方面至关重要：</p><ul><li>必须报告特定错误原因的系统工具</li><li>调试生产代码</li><li>编写可移植、可维护的程序</li></ul><p>优秀的 C 开发人员绝不会“默默地失败”。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>打开一个不存在的文件，然后创建它并重试。</li><li>使用以下命令模拟读取错误<code>ferror()</code>读取关闭的文件后。</li><li>尝试写入目录（<code>fopen(&quot;/tmp&quot;, &quot;w&quot;)</code>）并检查<code>errno</code>.</li><li>使用循环打印所有已知的错误代码和消息<code>strerror()</code>.</li><li>编写一个小的“safe_open”函数来包装<code>fopen</code>与错误报告。</li></ol><p>掌握错误处理后，您现在知道如何使 C 程序既丰富又可靠。接下来，您将探索命令行参数（<code>argc</code>,<code>argv</code>），构建灵活的、可编写脚本的工具来动态处理用户输入的门户。</p>`,49)])])}const g=n(t,[["render",o]]);export{u as __pageData,g as default};
